/**
 * The types `save/guardians/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    GuardianChipSaveRow, GuardianEquippedChipRow, GuardianSkinSaveRow, GuardianPresetSaveRow, GuardiansSaveExtract
 * depends    —
 * used by    src/save/guardians/index, src/save/guardians/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

// from read.ts

export interface GuardianChipSaveRow {
  slotIndex: number
  chipType: string | null
  targetKey: string | null
  label: string
  unlocked: boolean
  statLevels: number[]
  equippedSlot: number | null
}

export interface GuardianEquippedChipRow {
  equipSlot: number
  slotIndex: number
  label: string
  targetKey: string | null
  statLevels: number[]
}

export interface GuardianSkinSaveRow {
  index: number
  label: string
  unlocked: boolean
  selected: boolean
}

/** One guardian preset: its own chip levels, slots, equipped chips and skin (wiki "Guardian"). */
export interface GuardianPresetSaveRow {
  index: number
  name: string
  /** Whether the preset itself is unlocked; Presets lab level 5 opens 2, the Vault 3 more. */
  unlocked: boolean
  /** Chip catalog slot index in each equip slot, `-1` for an empty one. */
  equippedSlotIndices: number[]
  /** Chip slots this preset owns: the free first slot plus `slotsUnlocked` bought ones. */
  chipSlotCount: number
  skinIndex: number | null
  /** Three stat levels per chip, by chip catalog slot index. */
  chipLevels: number[]
}

export interface GuardiansSaveExtract {
  guardianUnlocked: boolean
  /** Official export membership flag. Missing/unreadable is unknown, not false. */
  inGuild: boolean | null
  /**
   * Whether the Guardian fights: unlocked, in a guild, with at least one chip equipped.
   * Guardian chips stopped working outside a guild in v29.1 (patch note 1560299109133459548); wiki
   * "Guardian" agrees. Null when guild membership is unknown.
   */
  activeInBattle: boolean | null
  /**
   * Chip slots owned: the Guardian comes with one, and `slotsUnlocked` counts the 2nd and 3rd
   * bought with bits (wiki "Currency/Bits"). 0 before the Guardian is unlocked.
   */
  chipSlotCount: number
  chips: GuardianChipSaveRow[]
  equippedChips: GuardianEquippedChipRow[]
  skins: GuardianSkinSaveRow[]
  /** Bought chip slots, as the save stores it. See `chipSlotCount` for slots owned. */
  slotsUnlocked: number | null
  skinIndex: number | null
  presets: GuardianPresetSaveRow[]
  /** The preset in use, by index into `presets`. */
  currentPreset: number | null
  totalDamage: unknown
  totalCoins: unknown
  totalCatches: unknown
  warnings: string[]
}
